10	/**
11	 * Rejects a supplied postcode that is not four digits, or that falls outside the
12	 * inclusive range fixed for the owner's city region (NSW 2000-2099, VIC 3000-3099,
13	 * QLD 4000-4099). A city with no known region accepts any four-digit postcode, and an
14	 * absent postcode is left untouched, so the request contract stays backward-compatible.
15	 */
16	public class ValidatePostcode {
17	
18	    private static final Map<String, int[]> CITY_RANGE = Map.of(
19	            "Sydney", new int[] {2000, 2099},
20	            "Melbourne", new int[] {3000, 3099},
21	            "Brisbane", new int[] {4000, 4099});
22	
23	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
24	        String postcode = owner.getPostcode();
25	        if (postcode == null) {
26	            return;
27	        }
28	        int[] range = CITY_RANGE.get(owner.getCity());
29	        boolean valid = postcode.matches("[0-9]{4}") && (range == null
30	                || (Integer.parseInt(postcode) >= range[0] && Integer.parseInt(postcode) <= range[1]));
31	        if (!valid) {
32	            throw new MissingOwnerFieldsException(List.of("postcode"));
33	        }
34	    }
35	}
