2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's locality (region code). It is the REGION segment of the owner's
9	 * {@code customerCode} identity ({@code <REGION>-<HASH8>}); only when no code has been
10	 * assigned yet does it fall back to {@link #region(Owner)}.
11	 */
12	public class Locality {
13	
14	    private static final Map<String, String> CITY_REGION = Map.of(
15	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
16	
17	    public static String locality(Owner owner) {
18	        String code = owner.getCustomerCode();
19	        int dash = code == null ? -1 : code.indexOf('-');
20	        return dash > 0 ? code.substring(0, dash) : region(owner);
21	    }
22	
23	    /**
24	     * Region code derived from the postcode: a four-digit postcode inside a known range
25	     * wins (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); otherwise it falls back to the
26	     * city-to-region table, which disambiguates cities that share a name.
27	     */
28	    public static String region(Owner owner) {
29	        String byPostcode = byPostcode(owner.getPostcode());
30	        return byPostcode != null ? byPostcode : CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
31	    }
32	
33	    private static String byPostcode(String postcode) {
34	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
35	            return null;
36	        }
37	        int p = Integer.parseInt(postcode);
38	        if (p >= 2000 && p <= 2099) return "NSW";
39	        if (p >= 3000 && p <= 3099) return "VIC";
40	        if (p >= 4000 && p <= 4099) return "QLD";
41	        return null;
42	    }
43	}
