30	    /** Lower-cases and collapses runs of whitespace to a single space so that
31	     *  case and spacing differences do not defeat the household match. */
32	    static String normalize(String value) {
33	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
34	    }
